// Phrasal Verbs section data.
//
// Three lists, each entry kept deliberately simple per the learner's ask:
// the phrasal verb, a short Bengali meaning of the verb itself, one English
// example sentence, and an original Bengali translation of that example.
// Nothing else — no synonyms, stories, games or quizzes.
//
// Sources (verb names + example sentences only; every Bengali translation
// below is written originally for this app):
//  - PV_COMMON: the most common phrasal verbs listed by Grammarly
//    (https://www.grammarly.com/blog/parts-of-speech/common-phrasal-verbs/),
//    in the order given in the learner's brief.
//  - PV_MORE: the "200 Phrasal Verbs List" from EnglishClub
//    (https://www.englishclub.com/vocabulary/phrasal-verbs-list.php).
//    A verb with more than one meaning on that page appears once per
//    meaning, exactly as listed there.
//  - PV_BUSINESS_GROUPS: "100 Phrasal Verbs for Business English" from
//    The English Center (https://englishcenter.nl/100-phrasal-verbs-for-business-english/),
//    kept in the page's own 10 groups of 10.

export type PhrasalVerb = {
  verb: string;
  /** Short Bengali meaning of the phrasal verb itself. */
  meaningBn: string;
  example: string;
  /** Bengali meaning of the example sentence. */
  exampleBn: string;
};

type Row = [string, string, string, string];
const toPv = (rows: Row[]): PhrasalVerb[] =>
  rows.map(([verb, meaningBn, example, exampleBn]) => ({ verb, meaningBn, example, exampleBn }));

